models.rs:321:     // narrows what models may be requested. Without these lines, "the model I
models.rs:322:     // asked for was refused" and "listing models never worked on that host"
models.rs:323:     // look identical from outside.
models.rs:324:     let listing = argv.join(" ");
models.rs:325:     let mut child = match command.spawn() {
models.rs:326:         Ok(child) => child,
models.rs:327:         Err(error) => {
models.rs:328:             tracing::warn!(command = %listing, %error, "could not list models");
models.rs:329:             return ModelCatalog::unavailable(format!("could not run model listing: {error}"));
models.rs:330:         }
models.rs:331:     };
models.rs:332:     let process_guard = crate::pi_client::ProcessTreeGuard::new(&child);
models.rs:333:     let stdout_task = child.stdout.take().map(|mut output| {
models.rs:334:         tokio::spawn(async move {
models.rs:335:             crate::pi_client::drain_bounded(&mut output, CATALOG_OUTPUT_LIMIT).await
models.rs:336:         })
models.rs:337:     });
models.rs:338:     let stderr_task = child.stderr.take().map(|mut output| {
models.rs:339:         tokio::spawn(async move {
models.rs:340:             crate::pi_client::drain_bounded(&mut output, CATALOG_ERROR_LIMIT).await
models.rs:341:         })
models.rs:342:     });
models.rs:343:     let status = match timeout(LIST_TIMEOUT, child.wait()).await {
models.rs:344:         Ok(Ok(status)) => {
models.rs:345:             process_guard.disarm();
models.rs:346:             status
models.rs:347:         }
models.rs:348:         outcome => {
models.rs:349:             match outcome {
models.rs:350:                 Ok(Err(error)) => {
models.rs:351:                     tracing::warn!(command = %listing, %error, "listing models failed")
models.rs:352:                 }
models.rs:353:                 _ => tracing::warn!(
models.rs:354:                     command = %listing,
models.rs:355:                     timeout = ?LIST_TIMEOUT,
models.rs:356:                     "listing models timed out"
models.rs:357:                 ),
models.rs:358:             }
models.rs:359:             crate::pi_client::terminate_process(&mut child).await;
models.rs:360:             process_guard.disarm();
models.rs:361:             if let Some(task) = stdout_task {
models.rs:362:                 task.abort();
models.rs:363:             }
models.rs:364:             if let Some(task) = stderr_task {
