models.rs:367:             return ModelCatalog::unavailable("model listing failed or timed out");
models.rs:368:         }
models.rs:369:     };
models.rs:370:     let stdout = match stdout_task {
models.rs:371:         Some(task) => task.await.unwrap_or_default(),
models.rs:372:         None => crate::pi_client::BoundedOutput::default(),
models.rs:373:     };
models.rs:374:     if let Some(task) = stderr_task {
