api.rs:99:     }
api.rs:100:     fn finish(&mut self, sequence: u64, generation: u64, audio: Vec<u8>) -> Vec<Event> {
api.rs:101:         let Some(slot) = self.slots.get_mut(&sequence) else {
api.rs:102:             return Vec::new();
api.rs:103:         };
api.rs:104:         if slot.generation == generation {
api.rs:105:             slot.audio = Some(audio);
api.rs:106:         } else {
api.rs:107:             slot.audio = Some(Vec::new());
api.rs:108:         }
api.rs:109:         let mut ready = Vec::new();
api.rs:110:         while let Some(slot) = self.slots.get(&self.emit) {
api.rs:111:             if slot.audio.is_none() {
api.rs:112:                 break;
api.rs:113:             }
api.rs:114:             let slot = self.slots.remove(&self.emit).expect("audio slot exists");
api.rs:115:             if let Some(audio) = slot.audio {
api.rs:116:                 if !audio.is_empty() {
api.rs:117:                     ready.push(Event::Audio {
api.rs:118:                         audio,
api.rs:119:                         generation: slot.generation,
api.rs:120:                         sequence: self.emit,
api.rs:121:                     });
api.rs:122:                 }
api.rs:123:             }
api.rs:124:             self.emit += 1;
api.rs:125:         }
api.rs:126:         ready
api.rs:127:     }
api.rs:128:     fn clear(&mut self) {
api.rs:129:         self.slots.clear();
api.rs:130:         self.emit = self.next;
api.rs:131:     }
api.rs:132: }
