agent-switchboard.ts:43: export default function agentSwitchboard(pi: ExtensionAPI) {
agent-switchboard.ts:44: 	// The switchboard asks for a thinking level on the command line, but the
agent-switchboard.ts:45: 	// runtime clamps it to what the model actually exposes — some models have
agent-switchboard.ts:46: 	// holes in their level map, and the clamp is silent. This session is the only
agent-switchboard.ts:47: 	// place the effective level is known, so it reports it: the page then states
agent-switchboard.ts:48: 	// a level the caller can act on rather than one that was merely requested.
agent-switchboard.ts:49: 	const reportThinking = async () => {
agent-switchboard.ts:50: 		if (!STATE_URL) return;
agent-switchboard.ts:51: 		try {
agent-switchboard.ts:52: 			await fetch(STATE_URL, {
agent-switchboard.ts:53: 				method: "POST",
agent-switchboard.ts:54: 				headers: { "Content-Type": "application/json" },
agent-switchboard.ts:55: 				body: JSON.stringify({
agent-switchboard.ts:56: 					thinking: pi.getThinkingLevel(),
agent-switchboard.ts:57: 					...(SESSION_TOKEN ? { token: SESSION_TOKEN } : {}),
agent-switchboard.ts:58: 				}),
agent-switchboard.ts:59: 				signal: AbortSignal.timeout(10_000),
agent-switchboard.ts:60: 			});
agent-switchboard.ts:61: 		} catch {
agent-switchboard.ts:62: 			// A label on a web page is never worth failing a call over.
agent-switchboard.ts:63: 		}
agent-switchboard.ts:64: 	};
agent-switchboard.ts:65: 
agent-switchboard.ts:66: 	pi.on("session_start", async () => {
